/**
 * Unit tests for ObjectReader._verifySchemaType
 */
public class ObjectReader__verifySchemaType_TriageGen0Test {

    private ObjectReader objectReader;

    @Mock
    private ObjectMapper mockMapper;

    @Mock
    private DeserializationConfig mockConfig;

    @Mock
    private FormatSchema mockSchema;

    @Mock
    private FormatParserFactory mockParserFactory;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        // Using the protected constructor via Reflection or a known path
        // Since ObjectReader is complex, we instantiate a minimal version
        objectReader = new ObjectReader(mockMapper, mockConfig);

        // Inject the private/protected _parserFactory field used in the method
        ReflectionTestUtils.setField(objectReader, "_parserFactory", mockParserFactory);
    }

    /**
     * Tests that when schema is null, no exception is thrown.
     * Covers the 'if (schema != null)' false branch.
     */
    @Test
    public void testVerifySchemaType_NullSchema() {
        objectReader._verifySchemaType(null);
        // No exception expected
        verifyNoInteractions(mockParserFactory);
    }

    /**
     * Tests that when schema is not null and parser factory can use it, no exception is thrown.
     * Covers the 'if (schema != null)' true branch and 'if (!_parserFactory.canUseSchema(schema))' false branch.
     */
    @Test
    public void testVerifySchemaType_ValidSchema() {
        when(mockParserFactory.canUseSchema(mockSchema)).thenReturn(true);

        objectReader._verifySchemaType(mockSchema);

        verify(mockParserFactory).canUseSchema(mockSchema);
    }

    /**
     * Tests that when schema is not null and parser factory cannot use it, an IllegalArgumentException is thrown.
     * Covers the 'if (!_parserFactory.canUseSchema(schema))' true branch.
     */
    @Test(expected = IllegalArgumentException.class)
    public void testVerifySchemaType_InvalidSchemaThrowsException() {
        when(mockParserFactory.canUseSchema(mockSchema)).thenReturn(false);
        when(mockParserFactory.getFormatName()).thenReturn("test-format");

        try {
            objectReader._verifySchemaType(mockSchema);
        } catch (IllegalArgumentException e) {
            // Verify the error message contains required info for full coverage of the exception logic
            assert(e.getMessage().contains("Can not use FormatSchema of type"));
            assert(e.getMessage().contains("test-format"));
            throw e;
        }
    }
}
